package e.e.a;
import java.io.*;import java.security.*;
public class InspectFragments{public static void main(String[] args)throws Exception{try(FragmentedMp4117 f=new FragmentedMp4117(new File(args[0]))){for(FragmentedMp4117.Format format:f.formats){System.out.println("FORMAT "+format.id+" "+format.mime+" "+format.width+" "+format.height+" "+format.rate+" "+format.channels+" "+format.scale);FragmentedMp4117.Cursor c=f.cursor(format);MessageDigest md=MessageDigest.getInstance("SHA-256");while(c.sample!=null){byte[] b=c.raw();md.reset();md.update(b,0,c.sample.size);StringBuilder hex=new StringBuilder();for(byte v:md.digest())hex.append(String.format("%02x",v&255));System.out.println("SAMPLE "+c.sample.timeUs+" "+c.sample.durationUs+" "+c.sample.size+" "+c.sample.sync+" "+hex);c.advance();}}}}}
